source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    comp = [[-1] * w for _ in range(h)]
    marker_color = {}
    cid = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or comp[r][c] >= 0:
                continue
            stack = [(r, c)]
            comp[r][c] = cid
            color = None
            while stack:
                y, x = stack.pop()
                if grid[y][x] > 1:
                    color = grid[y][x]
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0
                            and comp[yy][xx] < 0):
                        comp[yy][xx] = cid
                        stack.append((yy, xx))
            marker_color[cid] = color
            cid += 1

    # Find maximal solid rectangles of foreground at least 3 by 3,
    # then color their one-cell-inset interiors with their component marker.
    for top in range(h):
        columns = [True] * w
        for bottom in range(top, h):
            columns = [columns[c] and grid[bottom][c] != 0 for c in range(w)]
            if bottom - top + 1 < 3:
                continue
            c = 0
            while c < w:
                if not columns[c]:
                    c += 1
                    continue
                left = c
                while c < w and columns[c]:
                    c += 1
                right = c - 1
                if right - left + 1 < 3:
                    continue
                can_extend = (
                    (top > 0 and all(grid[top - 1][x] != 0 for x in range(left, right + 1)))
                    or (bottom + 1 < h and all(grid[bottom + 1][x] != 0 for x in range(left, right + 1)))
                    or (left > 0 and all(grid[y][left - 1] != 0 for y in range(top, bottom + 1)))
                    or (right + 1 < w and all(grid[y][right + 1] != 0 for y in range(top, bottom + 1)))
                )
                if can_extend:
                    continue
                color = marker_color[comp[top][left]]
                if color is None:
                    continue
                for r in range(top + 1, bottom):
                    for x in range(left + 1, right):
                        if grid[r][x] == 1:
                            out[r][x] = color
    return out
'''
